const $=selector=>document.querySelector(selector);
const categories={pessoa:'Pessoa',projeto:'Projeto (histórico interno)',acolhimento:'Acolhimento',voluntariado:'Voluntário',parcerias:'Parceria',contato:'Contato',operacao:'Atendimento ou entrega',acao:'Ação realizada'};
const plurals={pessoa:'Pessoas',projeto:'Projetos',acolhimento:'Acolhimentos',voluntariado:'Voluntários',parcerias:'Parcerias',contato:'Contatos',operacao:'Atendimentos e entregas',acao:'Ações realizadas'};
