const stateNames={novo:'Novo',em_contato:'Em contato',concluido:'Concluído',arquivado:'Arquivado',planejamento:'Em planejamento',em_andamento:'Em andamento',realizado:'Realizado',publicado:'Publicado',rascunho:'Rascunho'};
const views={inicio:['GESTÃO DO INSTITUTO','Início','Escolha uma tarefa e avance um passo de cada vez.'],'acoes-projetos':['COMUNICAÇÃO DOS PROJETOS','Ações e novidades','Compartilhe as atividades, os relatos e as fotos de cada projeto.'],crm:['PESSOAS, FAMÍLIAS E CUIDADO','Pessoas e atendimentos','Consulte os pedidos recebidos e organize o próximo passo de cada acompanhamento.'],acompanhamento:['DA SOLICITAÇÃO AO APOIO REALIZADO','Agenda e voluntariado','Organize inscrições de voluntariado e atividades da agenda. Pedidos e encaminhamentos são geridos no CRM.'],'video-chamada':['CONTEÚDO DO SITE','Vídeo de chamada','Confira e publique o vídeo de apresentação da página inicial.'],integracoes:['CANAIS E CONEXÕES','Configurações e integrações','Consulte o que está configurado e mantenha os canais oficiais atualizados.'],'documentos-internos':['MEMÓRIA E ORGANIZAÇÃO','Documentos internos','Consulte, baixe e organize os arquivos restritos à administração.'],'projetos-site':['CONTEÚDO PUBLICADO','Projetos do site','Edite a apresentação de cada projeto ou abra Ações e fotos para registrar uma atividade.'],'todos-dados':['CONSULTA COMPLETA','Todos os dados','Visualize os campos de todos os cadastros em fichas completas, sem entrar na edição.'],'visao-geral':['RESULTADOS CONFERIDOS','Resultados e histórico','Consulte os apoios confirmados e os indicadores anteriores, com critérios de contagem explícitos.'],cadastros:['UMA ÚNICA CENTRAL','Central de cadastros','Encontre, cadastre e altere todos os tipos de registro com o mesmo fluxo.'],publicacoes:['COMUNICAÇÃO COM O PÚBLICO','Publicações','Gerencie os relatos de ações e os resultados mensais divulgados no site.'],ajuda:['UM PASSO DE CADA VEZ','Como usar','Um caminho simples para consultar, registrar e publicar com segurança.']};
const personTypes=['pessoa','acolhimento','voluntariado','parcerias','contato'];
const brasiliaNow=()=>new Date(Date.now()-3*60*60*1000).toISOString(),monthNow=()=>brasiliaNow().slice(0,7),dateNow=()=>brasiliaNow().slice(0,10);
const number=value=>Number.isSafeInteger(value)?new Intl.NumberFormat('pt-BR').format(value):'Em apuração';
const date=value=>value?new Date(value.includes('T')?value:value+'T12:00:00').toLocaleDateString('pt-BR'):'—';
let updatesManager,recordViewer,operationsManager,mediaManager,integrationManager,confirmedManager,crmManager;
let page=1,overview,activity,publications=[],internalDocs=[],central={items:[],total:0},editing=null,lastFocus=null,currentView='inicio';
function el(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
function notice(message,success=false){const target=$('#global-message');target.textContent=message;target.hidden=!message;target.classList.toggle('success',success);}
async function api(path,data){const options={cache:'no-store'};if(data!==undefined){options.method='POST';if(data instanceof FormData)options.body=data;else{options.headers={'Content-Type':'application/json'};options.body=JSON.stringify(data);}}const response=await fetch(path,options);let body;try{body=await response.json();}catch{throw Error('O servidor não respondeu como esperado. Recarregue antes de tentar novamente.');}if(!response.ok)throw Error(body.error||'Não foi possível concluir a operação.');return body;}
function setView(name){if(!views[name])name='inicio';currentView=name;for(const key of Object.keys(views))$('#'+key).hidden=key!==name;for(const link of document.querySelectorAll('[data-view]')){if(link.dataset.view===name)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}for(const details of document.querySelectorAll('.sidebar details'))if(details.querySelector('a[aria-current=page]'))details.open=true;const[kicker,title,description]=views[name];$('#view-kicker').textContent=kicker;$('#view-title').textContent=title;$('#view-description').textContent=description;document.title=title+' | Gestão Mais Amor';if(name==='acoes-projetos')updatesManager?.ensureLoaded();if(name==='crm')crmManager?.ensureLoaded();if(name==='todos-dados')recordViewer?.ensureLoaded();if(name==='acompanhamento')operationsManager?.ensureLoaded();if(name==='video-chamada')mediaManager?.refresh?.();if(name==='integracoes')integrationManager?.refresh();}
function route(){const aliases={'resumo-gestao':'visao-geral','cadastros-gestao':'cadastros','publicar-resultados':'publicacoes','acoes-realizadas':'publicacoes','registros-atendimento':'cadastros','projetos-gestao':'cadastros','guia-equipe':'ajuda','transparencia':'documentos-internos','estatuto-social':'documentos-internos'};const hash=location.hash.slice(1);setView(aliases[hash]||hash||'inicio');}
window.addEventListener('hashchange',route);route();
for(const[key,title]of Object.entries(categories))$('#category-filter').add(new Option(title,key));
for(const[key,title]of Object.entries(allTypes))$('#record-type').add(new Option(title,key));
$('#overview-period').value=monthNow();
function renderOverview(){if(!overview)return;const p=overview.publicacao;const metrics=[['Alcance registrado',overview.pessoas,'Cadastros do mês + alcance complementar. Pode conter repetições.'],['Famílias apoiadas',p?.familias,'Resultado mensal conferido pela equipe.'],['Atendimentos realizados',overview.atendimentos,'Registros individuais + totais anteriores informados.'],['Cestas entregues',overview.cestas,'Entregas registradas + totais anteriores informados.'],['Voluntários registrados',overview.voluntarios,'Cadastros de voluntariado + quantidade complementar.'],['Cadastros recebidos',overview.cadastros,'Todos os cadastros criados no mês selecionado.'],['Ações publicadas',overview.acoes.find(row=>row.publicada===1)?.total||0,'Relatos publicados com data de realização neste mês.'],['Projetos concluídos',overview.projetos.filter(row=>row.situacao==='concluido').length,'Histórico geral dos projetos da administração.']];const root=$('#overview-cards');root.replaceChildren();for(const[title,value,hint]of metrics){const card=el('article',undefined,'metric-card'),strong=el('strong',number(value));if(!Number.isSafeInteger(value))strong.className='unavailable';card.append(el('span',title),strong,el('small',hint));root.append(card);}const totals=$('#category-totals');totals.replaceChildren();for(const[key,title]of Object.entries(plurals)){const row=el('div',undefined,'category-row');row.append(el('span',title),el('strong',String(activity?.totais.find(x=>x.categoria===key)?.total||0)));totals.append(row);}const history=$('#activity-list');history.replaceChildren();const auditNames={excluir_acao:'Relato excluído',atualizar_cadastro:'Cadastro atualizado',cadastrar_contato:'Contato cadastrado',atualizar:'Cadastro atualizado',atualizar_projeto:'Projeto atualizado',publicar_acao:'Ação publicada',salvar_rascunho:'Rascunho salvo',publicar_impacto:'Resultados mensais publicados',retirar_publicacao:'Publicação mensal retirada',registrar_atendimento:'Atendimento registrado',registrar_cesta:'Entrega registrada',registrar_outro:'Atividade registrada',excluir_registro_operacional:'Registro operacional excluído',excluir:'Cadastro excluído',anexar_arquivo:'Arquivo anexado',publicar_anexo:'Arquivo publicado',guardar_anexo_privado:'Arquivo definido como privado'};for(const row of activity?.items||[]){const line=el('div',undefined,'activity-item'),text=el('div');text.append(el('span',auditNames[row.acao]||(row.acao.startsWith('cadastrar_')?'Novo registro cadastrado':'Registro atualizado')),el('small',new Date(row.criado_em).toLocaleString('pt-BR')));line.append(text);history.append(line);}if(!activity?.items.length)history.append(el('p','As próximas alterações aparecerão aqui.'));}
function badge(text,published){return el('span',text,'badge '+(published===true?'published':published===false?'draft':(['novo','em_contato','planejamento'].includes(text)?'pending':'')));}
function editButton(category,id){const button=el('button','Editar','button secondary');button.type='button';button.addEventListener('click',()=>openEditor(category,id));return button;}
function renderCentral(){const root=$('#central-rows');root.replaceChildren();for(const row of central.items){const tr=el('tr'),title=el('td');const name=el('button',row.titulo,'record-name');name.type='button';name.setAttribute('aria-haspopup','dialog');name.addEventListener('click',()=>recordViewer.show(row.categoria,row.id));title.append(name,el('small',row.detalhe||'Sem informação complementar'));tr.className='record-clickable';tr.addEventListener('click',event=>{if(!event.target.closest('button,a,input,select,textarea')&&!window.getSelection()?.toString())recordViewer.show(row.categoria,row.id);});const state=el('td');state.append(badge(stateNames[row.situacao]||row.situacao,row.situacao==='publicado'?true:undefined));const actions=el('td'),buttons=el('div',undefined,'row-actions');const view=el('button','Visualizar','button secondary');view.type='button';view.addEventListener('click',()=>recordViewer.show(row.categoria,row.id));buttons.append(view,editButton(row.categoria,row.id));actions.append(buttons);tr.append(title,el('td',categories[row.categoria]||row.categoria),state,el('td',date(row.atualizado_em)),actions);root.append(tr);}$('#central-count').textContent=number(central.total)+' registro(s) encontrado(s)';$('#central-empty').hidden=central.items.length>0;$('#central-page').textContent='Página '+page+' de '+Math.max(1,Math.ceil(central.total/30));$('#central-prev').disabled=page===1;$('#central-next').disabled=page*30>=central.total;}
function renderPublications(){const filter=$('#publication-filter').value,rows=publications.filter(row=>!filter||(filter==='publicado'?!!row.publicado:filter==='rascunho'?!row.publicado:row.categoria===filter)),root=$('#publication-rows');root.replaceChildren();for(const row of rows){const tr=el('tr'),visibility=el('td');visibility.append(badge(row.publicado?'Público':row.categoria==='anexo'?'Privado':'Rascunho',!!row.publicado));const title=el('td');title.append(el('strong',row.titulo));const actions=el('td'),buttons=el('div',undefined,'row-actions');if(row.categoria==='anexo'){const download=el('a','Baixar','text-button');download.href='/api/anexos/'+encodeURIComponent(row.id);buttons.append(download);}buttons.append(editButton(row.categoria,row.id));actions.append(buttons);tr.append(title,el('td',allTypes[row.categoria]||row.categoria),visibility,el('td',date(row.atualizado_em)),actions);root.append(tr);}$('#publications-count').textContent=rows.length+' item(ns) nesta seleção';$('#publication-empty').hidden=rows.length>0;}
function renderDocuments(){
 const query=$('#documents-search').value.trim().toLocaleLowerCase('pt-BR'),rows=internalDocs.filter(row=>[row.titulo,row.descricao,row.nome].join(' ').toLocaleLowerCase('pt-BR').includes(query)),root=$('#documents-list');root.replaceChildren();
 for(const row of rows){const card=el('article',undefined,'internal-document-card');card.append(el('span',row.origem==='institucional'?'ESTATUTO · ORIGINAL FORNECIDO':'ARQUIVO INSTITUCIONAL','eyebrow'),el('h3',row.titulo),el('p',row.descricao||'Sem descrição complementar.'));card.append(el('small',row.nome+' · '+Math.ceil(row.tamanho/1024)+' KB'+(row.atualizado_em?' · Atualizado em '+date(row.atualizado_em):'')));const actions=el('div',undefined,'row-actions');for(const[label,href]of [['Consultar ↗',row.consulta],['Baixar ↓',row.download]]){const link=el('a',label,'button secondary');link.href=href;link.target='_blank';link.rel='noopener';actions.append(link);}if(row.origem==='anexo')actions.append(editButton('anexo',row.id));card.append(actions,el('span','Restrito à administração','badge draft'));root.append(card);}
 $('#documents-status').textContent=rows.length?rows.length+' documento(s) nesta seleção.':'Nenhum documento corresponde à busca.';
}
$('#documents-search').addEventListener('input',renderDocuments);
$('#documents-refresh').onclick=async()=>{const button=$('#documents-refresh');button.disabled=true;$('#documents-status').textContent='Atualizando documentos…';try{internalDocs=(await api('/api/admin/documentos')).items;renderDocuments();}catch(error){$('#documents-status').textContent=error.message;}finally{button.disabled=false;}};
async function loadCentral(){const query=new URLSearchParams(new FormData($('#central-filters')));query.set('pagina',page);central=await api('/api/admin/central?'+query);renderCentral();}
async function refreshAll(){const status=$('#sync-status');status.textContent='Atualizando dados…';status.classList.remove('failed');try{const[o,a,p,d]=await Promise.all([api('/api/admin/overview?periodo='+$('#overview-period').value),api('/api/admin/atividade'),api('/api/admin/publicacoes'),api('/api/admin/documentos')]);overview=o;activity=a;publications=p.items;internalDocs=d.items;renderOverview();renderPublications();renderDocuments();await loadCentral();recordViewer?.invalidate();operationsManager?.invalidate();crmManager?.invalidate();await confirmedManager?.refresh();status.textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});return true;}catch(error){status.textContent='Atualização indisponível';status.classList.add('failed');notice(error.message);return false;}}
$('#central-filters').addEventListener('submit',async event=>{event.preventDefault();page=1;try{await loadCentral();}catch(error){notice(error.message);}});$('#clear-filters').addEventListener('click',()=>{$('#central-filters').reset();page=1;loadCentral().catch(error=>notice(error.message));});$('#central-prev').onclick=()=>{page--;loadCentral().catch(error=>notice(error.message));};$('#central-next').onclick=()=>{page++;loadCentral().catch(error=>notice(error.message));};$('#publication-filter').onchange=renderPublications;$('#overview-period').onchange=refreshAll;$('#refresh-all').onclick=()=>{notice('');refreshAll();};
const dialog=$('#record-dialog'),form=$('#registro-form'),fields=$('#record-fields'),typeSelect=$('#record-type');
function field(name,title,type='text',options={}){const label=el('label',title),input=document.createElement(type==='textarea'?'textarea':type==='select'?'select':'input');if(type!=='textarea'&&type!=='select')input.type=type;input.name=name;input.id='field-'+name;label.htmlFor=input.id;if(options.choices)for(const[value,text]of options.choices)input.add(new Option(text,value));if(options.value!==undefined)input.value=options.value??'';if(options.required)input.required=true;for(const key of ['maxLength','minLength','min','max','step','accept','placeholder'])if(options[key]!==undefined)input[key]=options[key];label.append(input);if(options.hint)label.append(el('small',options.hint,'field-hint'));return label;}
function check(name,title,checked=false,publicCheck=false){const label=el('label',undefined,'check-label'+(publicCheck?' public-check':'')),input=document.createElement('input');input.type='checkbox';input.name=name;input.checked=checked;label.append(input,el('span',title));return label;}
const optionList=object=>Object.entries(object);
function renderFields(type,record={}){fields.replaceChildren();$('#record-feedback').textContent='';let guidance='',save='Salvar registro';const isEdit=!!editing;
 if(personTypes.includes(type)){guidance='Dados de contato e anotações ficam apenas na administração. O salvamento atualiza os indicadores do período de criação do cadastro.';fields.append(field('nome',type==='pessoa'?'Nome da pessoa':'Nome','text',{value:record.nome,required:true,minLength:2,maxLength:100}),field('contato','Telefone com DDD ou e-mail','text',{value:record.contato,required:type!=='pessoa',maxLength:150,hint:type==='pessoa'?'Opcional. Registre somente os dados necessários, sem documentos ou informações de saúde.':''}),field('organizacao','Organização ou área de interesse (opcional)','text',{value:record.organizacao,maxLength:150}),field('mensagem','Mensagem ou motivo do contato (opcional)','textarea',{value:record.mensagem,maxLength:600}),field('situacao','Situação do acompanhamento','select',{value:record.situacao||'novo',choices:optionList({novo:'Novo',em_contato:'Em contato',concluido:'Concluído',arquivado:'Arquivado'})}),field('notas','Anotações internas (opcional)','textarea',{value:record.notas,maxLength:2000}));const consent=check('ciente','Tenho autorização para registrar estes dados e realizar o retorno sobre a solicitação.',isEdit);consent.querySelector('input').required=true;fields.append(consent);save=isEdit?'Salvar alterações':'Cadastrar e atualizar indicadores';
 }else if(type==='projeto'){guidance='Este registro mantém o histórico interno. Para incluir, editar ou excluir projetos da página pública, use a aba Projetos do site, com capa e descrição completa.';fields.append(field('titulo','Nome do projeto','text',{value:record.titulo,required:true,minLength:3,maxLength:150}),field('situacao','Situação','select',{value:record.situacao||'planejamento',choices:optionList({planejamento:'Em planejamento',em_andamento:'Em andamento',concluido:'Concluído'})}));const dates=el('div',undefined,'field-row');dates.append(field('data_inicio','Data de início (opcional)','date',{value:record.data_inicio}),field('data_fim','Data de conclusão','date',{value:record.data_fim,max:dateNow(),hint:'Obrigatória para projetos concluídos.'}));fields.append(dates,field('resumo','Resumo interno do projeto','textarea',{value:record.resumo,maxLength:1000}),field('notas','Anotações internas (opcional)','textarea',{value:record.notas,maxLength:2000}));save='Salvar projeto';
 }else if(type==='operacao'){guidance='O registro atualiza os indicadores automaticamente, sem nova publicação mensal. Ao editar, a quantidade anterior é substituída para não duplicar o total.';fields.append(field('descricao_tipo','Qual atividade foi realizada?','text',{value:record.descricao_tipo,required:true,minLength:2,maxLength:120,placeholder:'Ex.: atendimento, visita ou entrega de alimentos'}),field('tipo','Como deve entrar na contagem?','select',{value:record.tipo||'atendimento',choices:optionList({atendimento:'Somar em atendimentos realizados',cesta:'Somar em cestas entregues',outro:'Outra atividade, sem somar nos dois indicadores'})}));const row=el('div',undefined,'field-row');row.append(field('data_ocorrencia','Data da ocorrência','date',{value:record.data_ocorrencia||dateNow(),required:true,max:dateNow()}),field('quantidade','Quantidade','number',{value:record.quantidade||1,min:1,max:100000,step:1,required:true}));fields.append(row);const linkField=field('cadastro_id','Vincular a uma pessoa ou contato (opcional)','select',{value:'',choices:[['','Sem vínculo']]});fields.append(linkField,field('notas','Observações internas (opcional)','textarea',{value:record.notas,maxLength:600}));const select=linkField.querySelector('select');loadContactOptions(select,record);save='Salvar e atualizar indicadores';
 }else if(type==='acao'){guidance='O relato só vai para o site quando a opção de publicação estiver marcada. Uma ação publicada atualiza a contagem do mês em que foi realizada.';fields.append(field('titulo','Título da ação','text',{value:record.titulo,required:true,minLength:3,maxLength:150}),field('data_realizacao','Data de realização','date',{value:record.data_realizacao||dateNow(),required:true,max:dateNow()}),field('resumo','Resumo público','textarea',{value:record.resumo,required:true,minLength:10,maxLength:500}),field('conteudo','Relato completo (opcional)','textarea',{value:record.conteudo,maxLength:10000}),check('publicada','Publicar este relato no site e contabilizar a ação nos resultados do mês.',!!record.publicada,true));save='Salvar ação';
 }else if(type==='anexo'){guidance='Documentos internos são exclusivos da administração, inclusive quando alguém tenta abrir o endereço direto do arquivo. Envie PDF, PNG, JPG ou WebP de até 5 MB. Informe a data e a versão na descrição. Não anexe documentos pessoais, laudos ou prontuários nesta biblioteca.';fields.append(field('titulo','Título do arquivo','text',{value:record.titulo,required:true,minLength:3,maxLength:150}),field('descricao','Descrição (opcional)','textarea',{value:record.descricao,maxLength:600}));if(!isEdit)fields.append(field('arquivo','Escolha o arquivo','file',{required:true,accept:'.pdf,.png,.jpg,.jpeg,.webp'}));else{const box=el('div');box.append(el('p','Arquivo: '+record.nome+' · '+Math.ceil(record.tamanho/1024)+' KB'));const download=el('a','Baixar arquivo atual','button secondary');download.href='/api/anexos/'+record.id+'?download=1';box.append(download);fields.append(box);}fields.append(el('p','Acesso restrito: este documento ficará somente em Documentos internos.','private-data-note'));save='Salvar documento interno';
 }else if(type==='resultado'){guidance='Informe somente números conferidos. Atendimentos, cestas e cadastros já lançados individualmente entram automaticamente; não os repita nos campos complementares.';fields.append(field('periodo','Mês de referência','month',{value:record.periodo||$('#overview-period').value||monthNow(),required:true,max:monthNow()}),field('familias','Famílias apoiadas no mês','number',{value:record.familias??0,required:true,min:0,max:100000000,step:1,hint:'Informe famílias distintas dentro do mês, sem repetir a mesma família por atendimento.'}));const detail=el('details');detail.append(el('summary','Informar totais anteriores ou complementares'));for(const[key,title]of Object.entries({pessoas:'Alcance adicional, sem repetir os cadastros',atendimentos:'Atendimentos anteriores não registrados individualmente',cestas:'Cestas anteriores não registradas individualmente',voluntarios:'Voluntários adicionais, sem cadastro no site'}))detail.append(field(key,title,'number',{value:record.base?.[key]??record[key]??0,required:true,min:0,max:100000000,step:1}));fields.append(detail,field('fonte','Fonte utilizada para conferir os resultados','text',{value:record.fonte,required:true,minLength:3,maxLength:300,placeholder:'Ex.: relatório de atividades do mês'}),field('parceiros','Parcerias formalizadas para divulgar (opcional)','textarea',{value:(record.parceiros||[]).join('\n'),maxLength:7500,hint:'Uma organização por linha. Informe somente parcerias confirmadas.'}));const consent=check('confirmado','Conferi os números e autorizo a publicação destes resultados consolidados no site.',false,true);consent.querySelector('input').required=true;fields.append(consent);save='Publicar resultados do mês';}
 $('#record-guidance').textContent=guidance;$('#record-save').textContent=save;updateSaveLabel();
}
function updateSaveLabel(){const type=typeSelect.value;if(type==='acao')$('#record-save').textContent=form.elements.publicada?.checked?'Publicar ação no site':'Salvar como rascunho';if(type==='projeto')$('#record-save').textContent=form.elements.publicado?.checked?'Salvar e divulgar projeto':'Salvar projeto interno';if(type==='anexo')$('#record-save').textContent='Salvar documento interno';}
async function loadContactOptions(select,record){try{const d=await api('/api/admin/entries');for(const row of d.items)select.add(new Option(row.nome+' · '+(categories[row.tipo]||row.tipo),row.id));if(record.cadastro_id&&![...select.options].some(o=>o.value===record.cadastro_id))select.add(new Option('Cadastro vinculado · '+record.cadastro_id.slice(0,8),record.cadastro_id));select.value=record.cadastro_id||'';const label=select.parentElement,search=document.createElement('input');search.type='search';search.placeholder='Buscar pessoa ou contato para vincular';search.setAttribute('aria-label','Buscar pessoa ou contato para vínculo');const button=el('button','Buscar contato','text-button');button.type='button';button.onclick=async()=>{try{const rows=await api('/api/admin/entries?busca='+encodeURIComponent(search.value)),previous=select.value;select.replaceChildren(new Option('Sem vínculo',''));for(const row of rows.items)select.add(new Option(row.nome+' · '+categories[row.tipo],row.id));if([...select.options].some(o=>o.value===previous))select.value=previous;}catch(error){$('#record-feedback').textContent=error.message;}};label.append(search,button);}catch(error){$('#record-feedback').textContent='O vínculo opcional não pôde ser carregado. '+error.message;}}
async function openEditor(type='pessoa',id){if(type==='acao'&&updatesManager){location.hash='acoes-projetos';await updatesManager.open({id});return;}lastFocus=document.activeElement;notice('');editing=null;form.reset();typeSelect.disabled=false;typeSelect.value=type;$('#record-save').disabled=false;$('#dialog-title').textContent=id?'Editar registro':'Novo registro';renderFields(type);if(!dialog.open)dialog.showModal();if(id){$('#record-save').disabled=true;$('#record-feedback').textContent='Carregando registro…';try{let row;if(type==='resultado'){const data=await api('/api/impacto');row=data.periodos.find(r=>r.periodo===id&&r.publicada);if(!row)throw Error('A publicação não foi encontrada.');}else row=(await api('/api/admin/registro?tipo='+encodeURIComponent(type)+'&id='+encodeURIComponent(id))).item;editing={type,id,row};typeSelect.disabled=true;renderFields(type,row);$('#record-save').disabled=false;}catch(error){$('#record-feedback').textContent=error.message;}}typeSelect.focus();}
function closeEditor(){dialog.close();editing=null;lastFocus?.focus();}
$('#new-record').onclick=()=>{location.hash='inicio';};for(const b of document.querySelectorAll('[data-create]'))b.onclick=()=>openEditor(b.dataset.create);for(const b of document.querySelectorAll('[data-go]'))b.onclick=()=>{location.hash=b.dataset.go;};$('#dialog-close').onclick=closeEditor;$('#dialog-cancel').onclick=closeEditor;dialog.addEventListener('cancel',()=>{editing=null;});typeSelect.onchange=()=>{editing=null;renderFields(typeSelect.value);};form.addEventListener('change',updateSaveLabel);
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const type=typeSelect.value,data=Object.fromEntries(new FormData(form)),id=editing?.id,button=$('#record-save');button.disabled=true;$('#record-feedback').textContent='Salvando no banco…';try{let result;
 if(personTypes.includes(type)){result=await api('/api/admin/entries',{id,tipo:type,nome:data.nome,contato:data.contato||'',organizacao:data.organizacao||'',mensagem:data.mensagem||'',situacao:data.situacao,notas:data.notas||'',ciente:data.ciente==='on'});
 }else if(type==='projeto'){result=await api('/api/admin/projetos',{id,titulo:data.titulo,situacao:data.situacao,data_inicio:data.data_inicio||'',data_fim:data.data_fim||'',resumo:data.resumo||'',notas:data.notas||'',publicado:data.publicado==='on'});
 }else if(type==='operacao'){result=await api('/api/admin/operacoes',{id,descricao_tipo:data.descricao_tipo,tipo:data.tipo,data_ocorrencia:data.data_ocorrencia,quantidade:Number(data.quantidade),cadastro_id:data.cadastro_id||'',notas:data.notas||''});
 }else if(type==='acao'){result=await api('/api/admin/acoes',{id,titulo:data.titulo,resumo:data.resumo,conteudo:data.conteudo||'',data_realizacao:data.data_realizacao,publicada:data.publicada==='on'});
 }else if(type==='anexo'){if(id)result=await api('/api/admin/anexos/atualizar',{id,titulo:data.titulo,descricao:data.descricao||'',publico:false});else{const file=form.elements.arquivo.files[0];if(file.size>5*1024*1024)throw Error('O arquivo deve ter no máximo 5 MB.');const upload=new FormData();upload.set('arquivo',file);upload.set('titulo',data.titulo);upload.set('descricao',data.descricao||'');upload.set('publico','false');result=await api('/api/admin/anexos',upload);}
 }else if(type==='resultado'){const values={periodo:data.periodo,fonte:data.fonte,parceiros:(data.parceiros||'').split('\n').map(x=>x.trim()).filter(Boolean),confirmado:data.confirmado==='on',acoes:0};for(const key of ['pessoas','familias','atendimentos','cestas','voluntarios'])values[key]=Number(data[key]||0);result=await api('/api/admin/impacto',values);}
 const period=personTypes.includes(type)?(editing?.row?.criado_em?.slice(0,7)||monthNow()):type==='resultado'?data.periodo:type==='operacao'?data.data_ocorrencia.slice(0,7):type==='acao'?data.data_realizacao.slice(0,7):null;if(period)$('#overview-period').value=period;closeEditor();const refreshed=await refreshAll();if(refreshed)notice(type==='anexo'?'Documento salvo na biblioteca interna, com acesso restrito à administração.':type==='resultado'?'Resultados publicados. O painel e o site consultam os mesmos dados.':'Registro salvo no banco. Os indicadores do período foram atualizados.',true);
 }catch(error){$('#record-feedback').textContent=error.message;}finally{button.disabled=false;updateSaveLabel();}});
$('#export-results').onclick=()=>{if(!overview)return;const values={periodo:$('#overview-period').value,alcance_registrado:overview.pessoas,familias:overview.publicacao?.familias??'Em apuração',atendimentos:overview.atendimentos,cestas:overview.cestas,voluntarios:overview.voluntarios,cadastros:overview.cadastros,acoes:overview.acoes.find(x=>x.publicada===1)?.total||0,projetos_concluidos:overview.projetos.filter(x=>x.situacao==='concluido').length};const cell=value=>'"'+String(value).replaceAll('"','""')+'"';const csv='\uFEFF'+[Object.keys(values),Object.values(values)].map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=el('a');a.href=url;a.download='resultados-mais-amor-'+values.periodo+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
updatesManager=initProjectUpdates();
recordViewer=initRecordViews({api,el,categories,stateNames,personTypes,openEditor,isVisible:()=>currentView==='todos-dados'});
confirmedManager=initConfirmedOverview();operationsManager=initOperationsAdmin();mediaManager=initMediaAdmin();integrationManager=initIntegrationsAdmin();
crmManager=initCrmAdmin({openAction(){openEditor('acao');},openLegacy(tab){location.hash="acompanhamento";setView("acompanhamento");operationsManager?.openTab?.(tab);},openRecord(category,id){recordViewer?.show(category,id);}});
refreshAll();
if(currentView==='acoes-projetos')updatesManager?.ensureLoaded();if(currentView==='crm')crmManager?.ensureLoaded();if(currentView==='acompanhamento')operationsManager?.ensureLoaded();if(currentView==='integracoes')integrationManager?.refresh();
window.addEventListener('admin-data-updated',event=>{if(/^20\d{2}-(0[1-9]|1[0-2])$/.test(event.detail?.periodo||''))$('#overview-period').value=event.detail.periodo;refreshAll();});
window.addEventListener('public-projects-updated',()=>refreshAll());
